/bin/bash -lc "npm test && node --input-type=module - <<'EOF'
import assert from 'node:assert/strict';
import { formatProjectLabel } from './src/labels.js';
assert.equal(formatProjectLabel('  Atlas   App ', 'active'), 'Atlas App [active]');
for (const args of [['   ', 'active'], ['Atlas', 'draft']]) {
  assert.throws(() => formatProjectLabel(...args), TypeError);
}
EOF"

